import sys

sys.path.append("/Workspace/Users/osarodionogbeborevans@yahoo.com/databricks-taxi-trip/taxi-trip-pipeline")

# COMMAND ----------

trips_df = spark.sql("SELECT * FROM workspace.taxi_trip.trips")
zones_df = spark.sql("SELECT * FROM workspace.taxi_trip.zones")

# COMMAND ----------

# MAGIC %sql
# MAGIC SELECT * FROM workspace.taxi_trip.trips

# COMMAND ----------

# MAGIC %sql
# MAGIC SELECT * FROM workspace.taxi_trip.zones

# COMMAND ----------

trips_df.show(2)

# COMMAND ----------

trips_df.printSchema()

# COMMAND ----------

trips_df.describe().show()

# COMMAND ----------

trips_df.summary().show()

# COMMAND ----------

from pyspark.sql.functions import col, sum

# COMMAND ----------

trips_df.select(col("passenger_count").isNull().cast("int").alias("passenger_count")).show()

# COMMAND ----------

null_counts = trips_df.select([sum(col(c).isNull().cast("int")).alias(c) for c in trips_df.columns])

null_counts.show()

# COMMAND ----------

null_counts_zones = zones_df.select([sum(col(c).isNull().cast("int")).alias(c) for c in zones_df.columns])
null_counts_zones.show()

# COMMAND ----------

trips_df.filter("passenger_count IS NULL").show()

# COMMAND ----------

trips_df.where(trips_df.DOLocationID.isNull()).display()

# COMMAND ----------

trips_df.where(col("passenger_count").isNull() & col("DOLocationID").isNull()).show()

# COMMAND ----------

